esqlQuery.esql:
TS metrics-supabase.metrics.otel-*
// Replication series only exist when a replica or slot is attached; the physical lag gauge
// matches the "Physical Replication Lag" dashboard panel aggregation.
// Both compared gauges use LAST_OVER_TIME so they describe the same instant; peak is context.
| STATS
    `Physical Lag (s)` = MAX(LAST_OVER_TIME(physical_replication_lag_physical_replication_lag_seconds)),
    `Replay Lag (s)` = MAX(LAST_OVER_TIME(pg_stat_replication_replay_lag)),
    `Peak Replay Lag (s)` = MAX(MAX_OVER_TIME(pg_stat_replication_replay_lag)),
    `WAL Replay Paused` = MAX(LAST_OVER_TIME(physical_replication_lag_is_wal_replay_paused)),
    `Connected To Primary` = MIN(LAST_OVER_TIME(physical_replication_lag_is_connected_to_primary))
  BY resource.attributes.supabase_project_ref
// Both gauges use -1 to mean "not applicable" (no replica attached), so negatives and absent
// series collapse to 0 rather than being read as measurements.
| EVAL
    `Physical Lag (s)` = CASE(`Physical Lag (s)` > 0, `Physical Lag (s)`, 0.0),
    `Replay Lag (s)` = CASE(`Replay Lag (s)` > 0, `Replay Lag (s)`, 0.0),
    `Peak Replay Lag (s)` = CASE(`Peak Replay Lag (s)` > 0, `Peak Replay Lag (s)`, 0.0)
| EVAL `Lag (s)` = CASE(`Physical Lag (s)` >= `Replay Lag (s)`, `Physical Lag (s)`, `Replay Lag (s)`)
// 300s of lag means a read replica is serving materially stale data. Tighten to 60 where
// replica reads are expected to be near-real-time.
| WHERE `Lag (s)` > 300
| SORT `Lag (s)` DESC
